// listReferredObjects returns the secrets referred by the given object.
// functions list***ReferredSecrets list the secrets referred by object,
// and the returned records are stored via UpdateReferencesToSecret to keep
// reference records between the object and referred secrets up to date.
func listReferredObjects(obj client.Object) []types.NamespacedName {
	switch obj := obj.(type) {
	case *corev1.Service:
		return listCoreV1ServiceReferredSecrets(obj)
	case *netv1.Ingress:
		return listNetV1IngressReferredSecrets(obj)
	case *netv1beta1.Ingress:
		return listNetV1beta1IngressReferredSecrets(obj)
	case *extv1beta1.Ingress:
		return listExtensionV1beta1IngressReferredSecrets(obj)
	case *kongv1.KongPlugin:
		return listKongPluginReferredSecrets(obj)
	case *kongv1.KongClusterPlugin:
		return listKongClusterPluginReferredSecrets(obj)
	case *kongv1.KongConsumer:
		return listKongConsumerReferredSecrets(obj)
	case *kongv1beta1.TCPIngress:
		return listTCPIngressReferredSecrets(obj)
	}
	return nil
}

func listCoreV1ServiceReferredSecrets(service *corev1.Service) []types.NamespacedName {
	if service.Annotations == nil {
		return nil
	}

	secretName := annotations.ExtractClientCertificate(service.Annotations)
	if secretName != "" {
		return []types.NamespacedName{{
			Namespace: service.Namespace,
			Name:      secretName,
		}}
	}
	return nil
}

func listNetV1IngressReferredSecrets(ingress *netv1.Ingress) []types.NamespacedName {
	referredSecretNames := make([]types.NamespacedName, 0, len(ingress.Spec.TLS))
	for _, tls := range ingress.Spec.TLS {
		referredSecretNames = append(referredSecretNames, types.NamespacedName{
			Namespace: ingress.Namespace,
			Name:      tls.SecretName,
		})
	}
	return referredSecretNames
}

